'use strict';
(()=>{const groups=[['Explore',[['Character directory','characters.html'],['Compare entries','compare.html'],['Data tables','index.html'],['All graphics','visual.html?tab=assets'],['Heroes & portraits','visual.html?tab=heroes'],['Monsters & bosses','visual.html?tab=monsters'],['NPC artwork','visual.html?tab=npcs'],['Items & equipment','visual.html?tab=items'],['Maps','visual.html?tab=maps']]],['Game rules & code',[['Damage calculation','research.html?file=Reports-damage-formula.md#evidence'],['XP & progression','research.html#xp'],['Reports & evidence','research.html#evidence'],['Lua source','research.html#scripts'],['Compiled code & assembly','research.html#code'],['Story events','research.html#events'],['Map references','research.html#maps'],['Unity archive inventory','research.html#bundles']]],['Files & help',[['Game files & downloads','files.html'],['File audit','research.html#audit'],['Research overview','research.html#findings'],['How to use','help.html']]]];
const nav=document.createElement('aside');nav.id='site-sidebar';nav.setAttribute('aria-label','Website navigation');nav.innerHTML='<a class="site-brand" href="characters.html">G <strong>GUARDIAN ATLAS</strong></a><button id="site-nav-close" aria-label="Close navigation">×</button>'+groups.map(([title,links])=>'<nav aria-label="'+title+'"><h2>'+title+'</h2>'+links.map(([label,href])=>'<a href="'+href+'">'+label+'</a>').join('')+'</nav>').join('');document.body.prepend(nav);document.body.classList.add('shared-layout');
const toggle=document.createElement('button');toggle.id='site-nav-toggle';toggle.textContent='☰ All sections';toggle.setAttribute('aria-controls','site-sidebar');toggle.setAttribute('aria-expanded','false');document.body.prepend(toggle);
const backdrop=document.createElement('button');backdrop.id='site-nav-backdrop';backdrop.setAttribute('aria-label','Close navigation');document.body.append(backdrop);
function open(value){document.body.classList.toggle('nav-open',value);toggle.setAttribute('aria-expanded',String(value));if(value)nav.querySelector('a').focus();else toggle.focus()}
toggle.onclick=()=>open(!document.body.classList.contains('nav-open'));document.querySelector('#site-nav-close').onclick=()=>open(false);backdrop.onclick=()=>open(false);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('nav-open'))open(false)});
const datasets=document.querySelector('#datasets');if(datasets){const d=document.createElement('details');d.className='site-tables';d.innerHTML='<summary>Browse data collections</summary>';d.append(document.querySelector('#dataset-search'),datasets);nav.append(d);const about=document.querySelector('#about');if(about)nav.append(about)}
function active(){const page=location.pathname.split('/').pop()||'index.html',params=new URLSearchParams(location.search);nav.querySelectorAll('nav a').forEach(a=>{const u=new URL(a.href),target=u.pathname.split('/').pop();let on=page===target;if(page==='character.html')on=target==='characters.html';if(target==='research.html')on=on&&u.hash===(location.hash||'#findings')&&(u.searchParams.has('file')?params.get('file')===u.searchParams.get('file'):!(u.hash==='#evidence'&&params.get('file')==='Reports-damage-formula.md'));if(target==='visual.html')on=on&&(u.searchParams.get('tab')||'assets')===(params.get('tab')||'assets');a.classList.toggle('current',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')})}
nav.addEventListener('click',e=>{if(e.target.closest('a')&&innerWidth<=800)open(false)});window.addEventListener('hashchange',active);window.addEventListener('popstate',active);document.addEventListener('click',()=>setTimeout(active,0));let refresh;document.addEventListener('input',()=>{clearTimeout(refresh);refresh=setTimeout(active,350)});active();
})();
